import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor
class BadExecutorConfig {
    fun bad(): ThreadPoolTaskExecutor {
        return ThreadPoolTaskExecutor().apply { // bad
            setCorePoolSize(10)
            setMaxPoolSize(20)
            initialize()
        }
    }
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor
class GoodExecutorConfig {
    fun good(): ThreadPoolTaskExecutor {
        return ThreadPoolTaskExecutor().apply {
            setCorePoolSize(10)
            setMaxPoolSize(20)
            setQueueCapacity(50)
            initialize()
        }
    }
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor
class GoodDefaultExecutorConfig {
    fun good(): ThreadPoolTaskExecutor {
        return ThreadPoolTaskExecutor().apply {
            initialize()
        }
    }
}
